"use client";
import { useState } from "react";
import { useRouter } from "next/navigation";
export function VerificationForm() { const router = useRouter(); const [loading, setLoading] = useState(false); const [error, setError] = useState(""); async function submit(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); setLoading(true); setError(""); const form = new FormData(event.currentTarget); const response = await fetch("/api/vendors/verify", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ documentType: form.get("documentType"), documentUrl: form.get("documentUrl") }) }); const result = await response.json(); if (!response.ok) { setError(result.error || "Unable to submit verification."); setLoading(false); return; } router.refresh(); event.currentTarget.reset(); setLoading(false); } return <form onSubmit={submit} className="mt-6 grid gap-4 rounded-xl border p-5"><h2 className="font-bold">Submit verification document</h2><label className="grid gap-1 text-sm font-semibold">Document type<select name="documentType" required className="rounded-lg border p-2 font-normal dark:bg-gray-800"><option value="">Choose a document</option><option>CAC registration</option><option>Government ID</option><option>Utility bill</option></select></label><label className="grid gap-1 text-sm font-semibold">Secure document URL or reference<input name="documentUrl" required className="rounded-lg border p-2 font-normal dark:bg-gray-800" placeholder="https://..." /></label>{error && <p className="text-sm text-red-600">{error}</p>}<button disabled={loading} className="w-fit rounded-lg bg-blue-600 px-4 py-2 text-sm font-bold text-white disabled:opacity-60">{loading ? "Submitting..." : "Submit for review"}</button></form>; }
